function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(x,y,w,h)}
function roundRect(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function circle(x,y,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function line(x1,y1,x2,y2,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
function seeded(n){const x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)}
function drawSky(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#192a42');g.addColorStop(.48,'#49647a');g.addColorStop(1,'#e1a16d');rect(0,0,W,H,g);
// distant haze and high clouds
const sunX=W*.73-camX*.025,sunY=H*.28;const glow=ctx.createRadialGradient(sunX,sunY,5,sunX,sunY,W*.4);glow.addColorStop(0,'#ffe9b47a');glow.addColorStop(.2,'#ffd9a133');glow.addColorStop(1,'#ffd9a100');rect(0,0,W,H,glow);circle(sunX,sunY,Math.min(W,H)*.055,'#ffe7b0');
for(let layer=0;layer<3;layer++){const parallax=.035+layer*.045,base=H*(.58+layer*.085),color=['#667b83','#405a62','#293f4a'][layer],step=190+layer*55;ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(0,H);for(let x=-step;x<=W+step;x+=step){const wx=(x+camX*parallax+world.width*4)%(W+step*2)-step;const peak=base-65-seeded(Math.floor((x+camX*parallax)/step)+layer*17)*100;ctx.lineTo(wx,base);ctx.lineTo(wx+step*.5,peak);ctx.lineTo(wx+step,base)}ctx.lineTo(W,H);ctx.closePath();ctx.fill();}
// floating ember motes
for(let i=0;i<24;i++){let x=(seeded(i+5)*W-camX*.09+elapsed*(4+seeded(i)*8))%W,y=H*(.22+seeded(i+40)*.55)+Math.sin(elapsed*.7+i)*8;circle((x+W)%W,y,1+seeded(i+99)*1.5,`rgba(255,218,156,${.2+seeded(i+6)*.35})`)} }
function drawTree(x,y,s,shade){ctx.save();ctx.translate(x,y);ctx.scale(s,s);rect(-9,-54,18,55,'#46382e');rect(-17,-18,8,7,'#594333');circle(0,-72,30,shade);circle(-18,-57,19,shade);circle(18,-56,20,shade);circle(0,-94,18,shade);ctx.restore()}
function drawWorld(){drawSky();ctx.save();ctx.scale(scale,scale);const viewW=W/scale,viewH=H/scale;const offsetY=(viewH-540)/2;
ctx.translate(0,offsetY);
// parallax forest silhouettes
for(let i=0;i<18;i++){const x=((i*197-camX*.25)%(world.width+300)+world.width+300)%(world.width+300)-80;if(x<viewW+70)drawTree(x,460,1.05+seeded(i)*.45,['#354c50','#3b5350','#34494b'][i%3]);}
// sunlit haze strips
const haze=ctx.createLinearGradient(0,260,0,480);haze.addColorStop(0,'#ffdea000');haze.addColorStop(1,'#ffcf7a24');rect(0,260,viewW,220,haze);
ctx.save();ctx.translate(-camX,0);
// ground / floating platforms
for(const p of platforms){rect(p.x,p.y,p.w,p.h,'#493f39');rect(p.x,p.y,p.w,9,'#817353');rect(p.x,p.y,p.w,4,'#a9a078');for(let i=0;i<p.w/26;i++){const xx=p.x+i*26;rect(xx,p.y+12,1,Math.min(30,p.h-12),'#59473b');if(seeded(Math.floor(xx)+2)>.5){rect(xx+5,p.y+24,6,3,'#635143')}}
for(let i=0;i<p.w/23;i++){const xx=p.x+i*23;rect(xx+3,p.y-4,9,4,['#789064','#8a986b','#687f5e'][i%3])}}
// glowing checkpoint stones
checkpoints.forEach(cp=>{rect(cp.x,cp.y-31,7,31,cp.active?'#fbdc86':'#84928a');circle(cp.x+3,cp.y-36,7,cp.active?'#ffd77c':'#bcc5a0');if(cp.active){ctx.globalAlpha=.35+Math.sin(elapsed*5)*.12;circle(cp.x+3,cp.y-36,16,'#ffdb7d');ctx.globalAlpha=1}});
// gate / destination
ctx.fillStyle='#192e39';ctx.beginPath();ctx.moveTo(gate.x-42,460);ctx.lineTo(gate.x-36,359);ctx.quadraticCurveTo(gate.x,305,gate.x+36,359);ctx.lineTo(gate.x+42,460);ctx.closePath();ctx.fill();ctx.strokeStyle='#c3975c';ctx.lineWidth=5;ctx.stroke();ctx.fillStyle='#ffcf79';ctx.globalAlpha=.45+.3*Math.sin(elapsed*3);ctx.beginPath();ctx.ellipse(gate.x,420,21,49,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
// coins
for(const c of coins)if(!c.taken){const bob=Math.sin(elapsed*4+c.x)*4;circle(c.x,c.y+bob,9,'#9b682d');circle(c.x,c.y+bob,7,'#ffd36f');circle(c.x-2,c.y+bob-2,2,'#fff0bd');rect(c.x-1,c.y+bob-4,2,8,'#e7a443')}
// enemies
for(const e of enemies)if(e.alive){const bob=Math.abs(Math.sin(elapsed*7+e.home)) * 3;ctx.save();ctx.translate(e.x,e.y-bob);ctx.fillStyle='#477755';ctx.beginPath();ctx.ellipse(0,-14,17,14,0,Math.PI,0);ctx.lineTo(17,-4);ctx.quadraticCurveTo(0,4,-17,-4);ctx.fill();ctx.fillStyle='#a5d17b';ctx.beginPath();ctx.ellipse(-4,-13,2.4,3.8,0,0,Math.PI*2);ctx.ellipse(5,-13,2.4,3.8,0,0,Math.PI*2);ctx.fill();circle(-3,-13,1.3,'#162a27');circle(6,-13,1.3,'#162a27');line(-7,-5,-3,-4,'#294a37',1.5);line(3,-4,7,-5,'#294a37',1.5);if(e.hp<2){roundRect(-12,-34,24,3,2,'#1c2a2a');roundRect(-12,-34,12,3,2,'#f1ba6b')}ctx.restore()}
drawHero();
// ambient foreground grass blades
for(let i=0;i<95;i++){const x=(i*51+camX*.12)%viewW,y=460+seeded(i+130)*11;line(x,y,x-3+Math.sin(elapsed+i)*2,y-9-seeded(i+1)*8,'#64724d',1.5)}
ctx.restore();ctx.restore();
}
function drawHero(){const h=hero;ctx.save();ctx.translate(h.x+h.w/2,h.y+h.h);ctx.scale(h.face,1);const blink=h.invuln>0&&Math.floor(elapsed*15)%2===0;if(blink)ctx.globalAlpha=.4;
// legs and little boots
const run=Math.sin(elapsed*17)*2.5*(Math.abs(h.vx)>20?1:0);roundRect(-9,-12+run,7,13,3,'#263342');roundRect(1,-12-run,7,13,3,'#263342');roundRect(-11,-3+run,10,5,2,'#a76543');roundRect(0,-3-run,10,5,2,'#a76543');
// cloak silhouette
ctx.fillStyle='#bd5142';ctx.beginPath();ctx.moveTo(-9,-39);ctx.quadraticCurveTo(-15,-26,-12,-12);ctx.lineTo(10,-11);ctx.lineTo(8,-38);ctx.closePath();ctx.fill();ctx.fillStyle='#833e3a';ctx.beginPath();ctx.moveTo(-8,-16);ctx.lineTo(10,-15);ctx.lineTo(8,-11);ctx.lineTo(-12,-11);ctx.fill();
// tunic / arm
roundRect(-5,-38,15,20,4,'#e0ad68');roundRect(-1,-33,13,5,2,'#f0c47b');circle(5,-46,9,'#d99b69');
// hair
ctx.fillStyle='#52372f';ctx.beginPath();ctx.arc(4,-48,9,Math.PI,Math.PI*2);ctx.lineTo(12,-44);ctx.lineTo(6,-45);ctx.lineTo(1,-42);ctx.closePath();ctx.fill();circle(8,-47,1.2,'#1b2430');
// sword arm and weapon
line(7,-31,17,-28,'#d89f70',4);if(h.attack>0){const progress=1-h.attack/.24;ctx.save();ctx.rotate(-.8+progress*1.7);line(13,-28,39,-31,'#e6e9df',4);line(13,-28,20,-28,'#9c7041',3);ctx.strokeStyle=`rgba(255,240,185,${.55*(1-progress)})`;ctx.lineWidth=2;ctx.beginPath();ctx.arc(10,-28,33,-1.2,.7);ctx.stroke();ctx.restore()}else{line(14,-28,31,-34,'#e7e5d6',3);line(14,-28,20,-29,'#9d7043',3)}ctx.restore();}

